/* Original mercenary poses: one decoded frame and one lazily uploaded actor slot. */
#include "mercenary_art180.h"
#define MERCENARY_KIND180 (SCRIPT_NPC_KIND55+SCRIPT_NPC_SLOTS55)
#define MERCENARY_TEXTURE180 (RENDER_MOBS+24)
static SparseSprite mercenarySprite180;static unsigned mercenaryFrame180=UINT32_MAX;
static void mercenary_render_release180(void){if(mercenarySprite180.raw||entityTextures[MERCENARY_TEXTURE180]){while(pb_busy()){}free(mercenarySprite180.raw);memset(&mercenarySprite180,0,sizeof(mercenarySprite180));if(entityTextures[MERCENARY_TEXTURE180])MmFreeContiguousMemory(entityTextures[MERCENARY_TEXTURE180]);entityTextures[MERCENARY_TEXTURE180]=NULL;uploadedSource[MERCENARY_TEXTURE180]=NULL;}mercenaryFrame180=UINT32_MAX;}
static int mercenary_read_pose180(unsigned frame){if(frame>=sizeof(mercenaryArt180)/sizeof(*mercenaryArt180))return 0;const MercenaryArt180*f=mercenaryArt180+frame;if(!f->packed||f->packed>70000||f->raw>70000||f->offset>MERCENARY_ART_BYTES180||f->packed>MERCENARY_ART_BYTES180-f->offset)return 0;HANDLE h=CreateFile("D:\\mercenary.bin",GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 0;DWORD high=0,got=0;unsigned char*p=malloc(f->packed);int ok=p&&!((GetFileSize(h,&high)!=MERCENARY_ART_BYTES180)||high)&&SetFilePointer(h,f->offset,NULL,FILE_BEGIN)==f->offset&&ReadFile(h,p,f->packed,&got,NULL)&&got==f->packed;CloseHandle(h);if(ok)ok=crc32(0,p,f->packed)==f->crc;if(ok){while(pb_busy()){}free(mercenarySprite180.raw);memset(&mercenarySprite180,0,sizeof(mercenarySprite180));sprite_load(&mercenarySprite180,"mercenary pose",p,f->packed,f->raw);mercenaryFrame180=frame;uploadedSource[MERCENARY_TEXTURE180]=NULL;uploadedFrames[MERCENARY_TEXTURE180]=UINT32_MAX;}free(p);return ok;}
static void mercenary_actors180(const Combat*g,const float*m,float co,float si,float zoom,DrawActor*actors,int*count){
 if(!mercenary_alive180(g)){mercenary_render_release180();return;}const Mercenary180*c=&g->mercenary180;const MercenaryData180*d=mercenary_data180(c->source);float z=height_at(c->x,c->y),sx,sy;world_project(m,c->x,c->y,z,&sx,&sy);if(sx< -80||sx>720||sy< -160||sy>560)return;
 unsigned dir=facing(c->faceX,c->faceY,co,si),group=g->time<c->attackUntil?2:g->time-c->hurtAt<.24f?3:c->moving?1:0;const MercenaryAction180*a=mercenaryActions180+mercenary_guild180(c->source)*40+group*8+dir;unsigned frame;
 if(group==2){float duration=c->attackUntil-c->attackAt,phase=duration>0?(g->time-c->attackAt)/duration:0;unsigned pose=(unsigned)(fmaxf(0,fminf(.999f,phase))*a->count);frame=a->first+pose;}else{float age=group==3?g->time-c->hurtAt:g->time;unsigned pose=(unsigned)(fmaxf(0,age)*1000)/a->ms;frame=a->first+(group==3?(pose<a->count?pose:a->count-1):pose%a->count);}
 if(frame!=mercenaryFrame180&&!mercenary_read_pose180(frame))return;float depth=m[8]*c->x+m[9]*c->y+m[10]*z+m[11]-WORLD_SPRITE_BIAS;actors[(*count)++]=(DrawActor){MERCENARY_TEXTURE180,MERCENARY_KIND180,0,sx,sy,depth,sy};(void)d;(void)zoom;
}
static void mercenary_arrow180(const Combat*g,const float*m,float zoom){const Mercenary180*c=&g->mercenary180;if(c->source>=6017&&c->source<=6026&&g->time>=c->shotAt&&g->time<=c->shotEnd)enemy_arrow_draw164(g,m,zoom,c->shotX,c->shotY,c->shotToX,c->shotToY,c->shotAt,c->shotEnd);}
